// Genuine Isolation Forest (Liu, Ting & Zhou 2008) implemented in TypeScript.
// Trained on synthetic baseline observations generated by the simulator.
// Not validated on real industrial data.

type Node =
  | { leaf: true; size: number }
  | { leaf: false; feature: number; split: number; left: Node; right: Node };

const EULER = 0.5772156649;
export function cFactor(n: number): number {
  if (n <= 1) return 0;
  if (n === 2) return 1;
  return 2 * (Math.log(n - 1) + EULER) - (2 * (n - 1)) / n;
}

function buildTree(data: number[][], depth: number, maxDepth: number): Node {
  if (depth >= maxDepth || data.length <= 1) return { leaf: true, size: data.length };
  const dims = data[0].length;
  const feature = Math.floor(Math.random() * dims);
  let min = Infinity;
  let max = -Infinity;
  for (const row of data) {
    if (row[feature] < min) min = row[feature];
    if (row[feature] > max) max = row[feature];
  }
  if (min === max) return { leaf: true, size: data.length };
  const split = min + Math.random() * (max - min);
  const l: number[][] = [];
  const r: number[][] = [];
  for (const row of data) (row[feature] < split ? l : r).push(row);
  return {
    leaf: false,
    feature,
    split,
    left: buildTree(l, depth + 1, maxDepth),
    right: buildTree(r, depth + 1, maxDepth),
  };
}

function pathLength(x: number[], node: Node, depth: number): number {
  if (node.leaf) return depth + cFactor(node.size);
  return pathLength(x, x[node.feature] < node.split ? node.left : node.right, depth + 1);
}

export class IsolationForest {
  private trees: Node[] = [];
  private sampleSize = 256;
  constructor(private nTrees = 100) {}

  fit(data: number[][]) {
    this.sampleSize = Math.min(256, data.length);
    const maxDepth = Math.ceil(Math.log2(this.sampleSize));
    this.trees = [];
    for (let t = 0; t < this.nTrees; t++) {
      const sample: number[][] = [];
      for (let i = 0; i < this.sampleSize; i++) sample.push(data[Math.floor(Math.random() * data.length)]);
      this.trees.push(buildTree(sample, 0, maxDepth));
    }
  }

  get trained() {
    return this.trees.length > 0;
  }
  get size() {
    return this.trees.length;
  }

  /** Anomaly score in (0,1]; >0.6 typically anomalous. */
  score(x: number[]): number {
    if (!this.trained) throw new Error("model not trained");
    let sum = 0;
    for (const t of this.trees) sum += pathLength(x, t, 0);
    const avg = sum / this.trees.length;
    return Math.pow(2, -avg / cFactor(this.sampleSize));
  }
}
